-- ============================================================================
-- Migration 009 - import September's real orders
-- ============================================================================
-- Written 6 Sep 2026, from the four workbooks in
--   PROSUN PACE\Sale Support current september files
--
-- WHAT GOES IN
--   322 orders, 1,236 lines, across all four channels:
--     Restaurant 177 - Department Store 100 - Individual 30 - Retail 15
--
--   Every customer matched the directory (322 of 322).
--   1,186 of 1,236 lines matched the catalogue (96%). The other 50 keep the
--   text that was written and resolve to no product - see note 4.
--
-- SAFE TO RE-RUN
-- Every id is computed from the order's own contents (channel, customer,
-- sheet, dates, and its position among identical rows), not generated fresh.
-- Running this twice inserts nothing the second time. It also means a
-- correction made in the app is NOT overwritten by a re-run.
--
-- WHAT THIS DELIBERATELY DOES NOT DO
--   * It does not guess an entity. Odoo decides who invoices.
--   * It does not guess a product for the 50 unmatched lines.
--   * It does not set a line status. Nothing on the sheets says whether a
--     delivery happened, and inventing "Pending" for a week already delivered
--     would be worse than leaving it blank.
--   * It does not attribute the orders to Jane, Tod or Nam. created_by stays
--     empty because this is an import, not something a person typed.
--
-- Run order: after 008. Run on staging first, check the counts at the bottom,
-- then production.
-- ============================================================================


-- ----------------------------------------------------------------------------
-- 0. Refuse to run if 008 has not been run
-- ----------------------------------------------------------------------------
-- Without 008 there is nowhere to put a standing-order date, an unconfirmed
-- quantity or an unmatched product name, and the failure would come out as a
-- column-not-found error two hundred lines down with half the work done.
-- Better to stop on the first line with a sentence that says what to do.
do $$
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'sale_order_lines'
      and column_name = 'quantity_tbc'
  ) then
    raise exception 'Migration 008 has not been run on this database yet. Run 008_standing_orders.sql first, then run this file again.';
  end if;
end $$;


-- ----------------------------------------------------------------------------
-- 1. Order date has to be allowed to be empty
-- ----------------------------------------------------------------------------
-- 108 of the 322 orders have no date in the Date column - almost all of
-- Department Store, where the sheet has no such column at all. The constraint
-- said every order has an order date; the real sheets say otherwise.
--
-- The alternative was to fill the blanks with the delivery date or with
-- today's date. Both would be inventing a fact, and order_date is exactly the
-- field someone would later trust to answer "when did they place this". An
-- empty cell should read as empty.
--
-- delivery_date is what the calculator uses, and that is present on every row.
alter table public.sale_orders alter column order_date drop not null;

comment on column public.sale_orders.order_date is
  'The date written in the Date column of the source sheet, when there is one. '
  'Often empty - several channels do not record it. For a standing order this '
  'is the date the arrangement began, and standing_since carries the same '
  'value to mark it as such.';


-- ----------------------------------------------------------------------------
-- 2. Staging
-- ----------------------------------------------------------------------------
-- The sheets identify a customer by name and a product by name. The database
-- identifies both by id, and those ids differ between staging and production
-- because each was seeded separately. So the rows land in temporary tables
-- first and the ids are resolved by name on the way in. That is also why this
-- same file works unchanged against both projects.
--
-- These tables exist only for the duration of this script.
drop table if exists _imp_orders;
drop table if exists _imp_lines;

create temporary table _imp_orders (
  id             uuid,
  channel        text,
  customer_name  text,
  customer_code  text,
  po_number      text,
  order_number   text,
  address        text,
  order_date     date,
  delivery_date  date,
  standing_since date,
  note           text,
  total_order    numeric,
  delivery_fee   numeric,
  total_amount   numeric,
  payment_text   text,
  paid           boolean,
  paid_date      date,
  payment_method text,
  sheet          text
);

create temporary table _imp_lines (
  id            uuid,
  order_id      uuid,
  type          text,
  product_name  text,
  description   text,
  quantity      numeric,
  quantity_tbc  boolean,
  unit          text,
  packaging     text,
  weight_label  text,
  weight_min_kg numeric,
  weight_max_kg numeric
);


-- ----------------------------------------------------------------------------
-- 3. The orders as they were written
-- ----------------------------------------------------------------------------
-- Three delivery-date cells hold Thai status text instead of a date
-- (rows awaiting confirmation or payment). Those keep an empty delivery_date
-- and the text is preserved in the order's note, so nothing is lost and
-- nothing is mistaken for a date.
--
-- 89 orders are standing arrangements - 45 say so in the PO column, 84 carry
-- an order date well before September, and 40 do both. Clement, 6 Sep 2026:
-- *"its the beggining of the standing order date."* So standing_since gets
-- that date rather than the row being treated as stale data.







-- ----------------------------------------------------------------------------
-- 4. The lines
-- ----------------------------------------------------------------------------
-- 71 lines were written as `x` rather than a number. Clement, 6 Sep 2026:
-- *"we know the client has a standing order, but we don't know the quantity of
-- this week yet."* Those get quantity_tbc = true and no quantity, so the
-- calculator can count them as unknown instead of as zero.
--
-- product_name holds what was written on every line, matched or not. The 50
-- that do not match the catalogue are mostly shorthand the team types instead
-- of the dropdown text - "Chicken Breast" without the suffix, 43 of the 50 -
-- and a handful genuinely absent from the list (chicken skin, breakfast
-- sausage, smoked chicken filet, a Western option). They will appear in the
-- unmatched_products view from 008 for sale support to correct or add.












-- ----------------------------------------------------------------------------
-- 5. Resolve names to ids and insert
-- ----------------------------------------------------------------------------
-- left join, not join: an order whose customer is missing from the directory
-- still goes in, carrying its name. Losing a real order because a name does
-- not match would be the worse failure.
  id, channel, customer_name, customer_code, pace_customer_id,
  po_number, order_number, delivery_address,
  order_date, delivery_date, standing_since, note,
  total_order, delivery_fee, total_amount,
  payment_status_text, paid, paid_date, payment_method
)
select i.id, i.channel, i.customer_name, i.customer_code, c.id,
       i.po_number, i.order_number, i.address,
       i.order_date, i.delivery_date, i.standing_since, i.note,
       i.total_order, i.delivery_fee, i.total_amount,
       i.payment_text, i.paid, i.paid_date, i.payment_method
from _imp_orders i
left join public.pace_customers c
       on c.channel = i.channel
      and lower(c.name) = lower(i.customer_name)
on conflict (id) do nothing;

-- Same idea for products. The catalogue is unique on (channel, type, name),
-- so this matches at most one row, and no row at all for the 50 that are
-- shorthand or genuinely absent.
  id, order_id, type, product_id, product_name, description,
  quantity, quantity_tbc, unit, packaging,
  weight_label, weight_min_kg, weight_max_kg
)
select l.id, l.order_id, l.type, p.id, l.product_name, l.description,
       l.quantity, l.quantity_tbc, l.unit, l.packaging,
       l.weight_label, l.weight_min_kg, l.weight_max_kg
from _imp_lines l
join public.sale_orders o on o.id = l.order_id
left join public.order_products p
       on p.channel = o.channel
      and p.type = l.type
      and lower(p.name) = lower(l.product_name)
on conflict (id) do nothing;

-- ----------------------------------------------------------------------------
-- 6. Check what actually landed
-- ----------------------------------------------------------------------------
-- Returned as a table rather than printed as notices, because the Supabase SQL
-- Editor shows query results but not notices - a check nobody can see is not a
-- check.
--
-- Counted against the staging tables, so the figures mean "what this import put
-- in" even on a database that already has a few test orders in it.
--
-- The staging tables are temporary: they disappear on their own when the editor
-- tab's connection closes, and the drop at the top of this file clears them if
-- it is run again in the same session. Nothing is left behind.
--
-- READ THE "ok" COLUMN. Every row must say ok. If any row says CHECK, stop
-- there and do not run this on production.
with counted as (
  select
    (select count(*) from public.sale_orders o join _imp_orders i on i.id = o.id)            as orders_in,
    (select count(*) from public.sale_order_lines l join _imp_lines i on i.id = l.id)        as lines_in,
    (select count(*) from public.sale_orders o join _imp_orders i on i.id = o.id
      where o.standing_since is not null)                                                    as standing,
    (select count(*) from public.sale_order_lines l join _imp_lines i on i.id = l.id
      where l.quantity_tbc)                                                                  as tbc,
    (select count(*) from public.sale_orders o join _imp_orders i on i.id = o.id
      where o.pace_customer_id is null)                                                      as no_customer,
    (select count(*) from public.sale_order_lines l join _imp_lines i on i.id = l.id
      where l.product_id is null)                                                            as no_product,
    (select count(*) from _imp_lines i
      where not exists (select 1 from public.sale_order_lines l where l.id = i.id))          as not_landed,
    (select count(*) from public.sale_order_lines l
      where not exists (select 1 from public.sale_orders o where o.id = l.order_id))         as orphans
),
checks (sort, label, actual, expected) as (
  select 1, 'orders imported',                   orders_in,   322 from counted
  union all select 2, 'lines imported',          lines_in,   1236 from counted
  union all select 3, 'standing arrangements',   standing,     89 from counted
  union all select 4, 'quantities still unknown (x)', tbc,     71 from counted
  union all select 5, 'orders not matched to a customer', no_customer, 0 from counted
  union all select 6, 'lines not on the product list',    no_product, 50 from counted
  union all select 7, 'lines that did not land at all',   not_landed,  0 from counted
  union all select 8, 'orphan lines anywhere in the book', orphans,    0 from counted
)
select label, actual, expected,
       case when actual = expected then 'ok' else 'CHECK' end as ok
from checks
order by sort;

-- ============================================================================
-- The last statement returns eight rows. Every one must read "ok" in the last
-- column. If any reads CHECK, stop and say so before touching production.
--
-- Running this file a second time is harmless and returns the same eight rows.
-- The ids are computed from the orders themselves, so nothing is inserted
-- twice - and a correction someone makes in the app is not undone by a re-run.
--
-- Then, in the app: open PROSUN PACE, use the arrows to reach a September week,
-- and check the table fills. And run
--
--   select * from public.unmatched_products order by line_count desc;
--
-- which is the list for Jane - nine entries, each either shorthand to correct
-- or a product that should be added to the catalogue.
-- ============================================================================
